            f"{where}.reference must be the first {where}.configs name"
        )

    data = summary["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    n_scenarios = len(scenarios)
    n_regions = len(regions)
    if len(data) != n_scenarios * n_regions:
        raise ValueError(
            f"{where}.data must contain exactly one row per "
            "(scenario, region) pair"
        )

    row_index = 0
    for scenario in scenarios:
        for region in regions:
            row_where = f"{where}.data[{row_index}]"
            row = data[row_index]
            if not isinstance(row, dict):
                raise TypeError(f"{row_where} must be a dict")
            if tuple(row.keys()) != _REGION_WEIGHT_SUMMARY_ROW_KEYS:
                raise ValueError(
                    f"{row_where} must have exactly the keys scenario, "
                    "region, count, rank_min, rank_max, magnitude_min, "
                    "magnitude_max, rank_std, magnitude_std, uncertainty "
                    "in order"
                )

            if not isinstance(row["scenario"], str):
                raise TypeError(f"{row_where}.scenario must be a str")
            if row["scenario"] != scenario:
                raise ValueError(
                    f"{row_where}.scenario must be {scenario!r} for its "
                    "position"
                )
            if not isinstance(row["region"], str):
                raise TypeError(f"{row_where}.region must be a str")
            if row["region"] != region:
                raise ValueError(
                    f"{row_where}.region must be {region!r} for its "
                    "position"
                )

            count = row["count"]
            if not isinstance(count, int) or isinstance(count, bool):
                raise TypeError(f"{row_where}.count must be a non-bool int")
            if count < 0 or count > len(configs) - 1:
                raise ValueError(
                    f"{row_where}.count must be between 0 and the "
                    "non-reference configuration count"
                )

            stats = [row[key] for key in _REGION_WEIGHT_SUMMARY_STAT_KEYS]
            none_flags = [stat is None for stat in stats]
            if any(none_flags) and not all(none_flags):
                raise ValueError(
                    f"{row_where}: rank_min, rank_max, magnitude_min, "
                    "magnitude_max, rank_std, magnitude_std and "
                    "uncertainty must be all None or all numbers"
                )
            if all(none_flags):
                if count == 0:
                    row_index += 1
                    continue
                row_index += 1
                continue
            if count == 0:
                raise ValueError(
                    f"{row_where}: the seven statistics must be None "
                    "when count is zero"
                )

            for key in _REGION_WEIGHT_SUMMARY_STAT_KEYS:
                _validate_number(row[key], f"{row_where}.{key}", nullable=False)
            if row["rank_min"] > row["rank_max"]:
                raise ValueError(
                    f"{row_where}.rank_min must not exceed "
                    f"{row_where}.rank_max"
                )
            if row["magnitude_min"] > row["magnitude_max"]:
                raise ValueError(
                    f"{row_where}.magnitude_min must not exceed "
                    f"{row_where}.magnitude_max"
                )
            for key in ("rank_std", "magnitude_std", "uncertainty"):
                if row[key] < 0:
                    raise ValueError(
                        f"{row_where}.{key} must be non-negative"
                    )
            row_index += 1

    return reference, configs, scenarios, elements, regions, data


def weight_robustness(summary, *, minimum: int = 1) -> dict:
    """Score region-weight summary robustness per scenario and region.

    ``summary`` must be a complete :func:`weight_summary` result (schema
    ``climate-grid/rws-v1``) with exactly the keys ``schema, reference,
    configs, scenarios, elements, regions, data`` in that order; every
    member is validated against that contract, including the flat
    scenario-then-region ``data`` row order, each row's key order
    ``scenario, region, count, rank_min, rank_max, magnitude_min,
    magnitude_max, rank_std, magnitude_std, uncertainty`` and the
    all-present or all-``None`` combination of the seven statistics.
    ``minimum`` must be a non-bool positive int.

    For every scenario (in scenario order) and region (in region order),
    when the row's ``count`` is below ``minimum`` or any of the seven
    statistics is ``None``, ``score`` and ``interval`` are both ``None``.
    Otherwise ``span`` is ``magnitude_max - magnitude_min``, ``score`` is
    ``hypot(rank_std, magnitude_std, span)`` and ``interval`` is
    ``[max(0, score - uncertainty), score + uncertainty]``.

    The returned mapping uses the key order ``schema, scenarios,
    elements, regions, data``; ``schema`` is
    ``climate-grid/rws-robust-v1`` and ``scenarios``, ``elements`` and
    ``regions`` echo the summary unchanged.  ``data`` is a flat list in
    scenario-then-region order; each row uses the key order ``scenario,
    region, count, score, interval``.  ``count`` is an int, ``score`` is
    a float or ``None``, ``interval`` is a two-item float list or
    ``None`` and every output float is ``round(x, 12)`` with negative
    zero normalized to ``0.0``.  The input is not modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation, including
    non-finite results.
    """
    _reference, _configs, scenarios, elements, regions, data = (
        _validate_region_weight_summary(summary)
    )

    if not isinstance(minimum, int) or isinstance(minimum, bool):
        raise TypeError("minimum must be a non-bool int")
    if minimum < 1:
        raise ValueError("minimum must be positive")

    rows = []
    for row in data:
        count = row["count"]
        stats = [row[key] for key in _REGION_WEIGHT_SUMMARY_STAT_KEYS]
        if count < minimum or any(stat is None for stat in stats):
            rows.append(
                {
                    "scenario": row["scenario"],
                    "region": row["region"],
                    "count": count,
                    "score": None,
                    "interval": None,
                }
            )
            continue

        span = float(row["magnitude_max"]) - float(row["magnitude_min"])
        uncertainty = float(row["uncertainty"])
        try:
            score = math.hypot(
                float(row["rank_std"]), float(row["magnitude_std"]), span
            )
        except OverflowError:
            raise ValueError("results must be finite") from None
        lower = max(0.0, score - uncertainty)
        upper = score + uncertainty
        if not (_is_finite(score) and _is_finite(lower) and _is_finite(upper)):
            raise ValueError("results must be finite")

        rows.append(
            {
                "scenario": row["scenario"],
                "region": row["region"],
                "count": count,
                "score": _round_output(score),
                "interval": [_round_output(lower), _round_output(upper)],
            }
        )

    return {
        "schema": _REGION_WEIGHT_ROBUSTNESS_SCHEMA,
        "scenarios": list(scenarios),
        "elements": list(elements),
        "regions": list(regions),
        "data": rows,
    }

